@cache
def dp(i):
    if i <= 1:
        return 1
    return dp(i - 1) + dp(i - 2)

parent = list(range(n))
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(a, b):
    parent[find(a)] = find(b)
